extension MactermProtocol {
    /// The codes of `ErrorInfo.code`. `unknown` holds a code that a later build added.
    enum ErrorCode: Equatable {
        case busy
        case exited
        case forbidden
        case invalidArgs
        case notFound
        case refused
        case startFailed
        case starting
        case timeout
        case unavailable
        case unknownMethod
        case duplicateId
        case modelReadonly
        case unknown(String)

        init(_ code: String) {
            switch code {
            case "busy": self = .busy
            case "exited": self = .exited
            case "forbidden": self = .forbidden
            case "invalid_args": self = .invalidArgs
            case "not_found": self = .notFound
            case "refused": self = .refused
            case "start_failed": self = .startFailed
            case "starting": self = .starting
            case "timeout": self = .timeout
            case "unavailable": self = .unavailable
            case "unknown_method": self = .unknownMethod
            case "duplicate_id": self = .duplicateId
            case "model_readonly": self = .modelReadonly
            default: self = .unknown(code)
            }
        }
    }
}

extension MactermProtocol.ErrorInfo {
    var errorCode: MactermProtocol.ErrorCode {
        .init(code)
    }
}

